export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null GIT_AUTHOR_NAME=Fixture GIT_AUTHOR_EMAIL=fixture@example.com GIT_COMMITTER_NAME=Fixture GIT_COMMITTER_EMAIL=fixture@example.com
export GIT_AUTHOR_DATE='2020-03-01T00:00:00Z' GIT_COMMITTER_DATE='2020-03-01T00:00:00Z'
K=$HOME/key
yn() { if "$@"; then echo yes; else echo no; fi; }
has() { case $1 in *"$2"*) echo yes;; *) echo no;; esac; }
cleanup() { cd /tmp/parity-case; /bin/rm -rf r; }
newrepo() { /usr/bin/git init -q -b main "$1"; cd "$1"; printf 'base\n' > f1; git add f1; git commit -q -m base; }
newrepo r
printf 'x\n' > f2; git add f2
git -c gpg.format=ssh -c user.signingKey="$K" commit -q -S -m signed 2>"$HOME/err.txt"; echo "commit-rc=$?"
git cat-file commit HEAD > "$HOME/commit.txt"
/usr/bin/python3 - "$HOME" <<'PY'
import sys,subprocess
home=sys.argv[1]; raw=open(home+'/commit.txt','rb').read()
head,_,msg=raw.partition(b'\n\n'); lines=head.split(b'\n'); sig=[]; keep=[]; ins=False
for l in lines:
    if l.startswith(b'gpgsig '): ins=True; sig.append(l[7:])
    elif ins and l.startswith(b' '): sig.append(l[1:])
    else: ins=False; keep.append(l)
print('gpgsig-header=%s' % ('yes' if sig else 'no'))
open(home+'/sig.txt','wb').write(b'\n'.join(sig)+b'\n'); open(home+'/payload.txt','wb').write(b'\n'.join(keep)+b'\n\n'+msg)
r=subprocess.run(['/usr/bin/ssh-keygen','-Y','verify','-f',home+'/allowed_signers','-I','fixture@example.com','-n','git','-s',home+'/sig.txt'],stdin=open(home+'/payload.txt','rb'),capture_output=True)
print('ssh-keygen-verifies-signature=%s' % ('yes' if r.returncode==0 else 'no'))
PY
echo "object-bytes:"; /usr/bin/python3 -c "import sys;sys.stdout.write(open('$HOME/commit.txt').read())"
cleanup

